const detail = ({
  audience,
  documents,
  data,
  conditions,
  steps,
  time,
  cost,
  result,
  rejection,
  description,
}) => Object.fromEntries(Object.entries({
  targetAudienceRu: audience[0], targetAudienceKz: audience[1],
  requiredDocumentsRu: documents[0], requiredDocumentsKz: documents[1],
  requiredDataRu: data?.[0], requiredDataKz: data?.[1],
  conditionsRu: conditions[0], conditionsKz: conditions[1],
  stepsRu: steps?.[0], stepsKz: steps?.[1],
  processingTimeRu: time[0], processingTimeKz: time[1],
  costRu: cost[0], costKz: cost[1],
  resultRu: result[0], resultKz: result[1],
  rejectionReasonsRu: rejection?.[0] ?? commonRefusalRu,
  rejectionReasonsKz: rejection?.[1] ?? commonRefusalKz,
  fullDescriptionRu: description?.[0], fullDescriptionKz: description?.[1],
}).filter(([, value]) => value !== undefined));

